var SITE = 'https://e5f6g7h8.ssxxs014.cc';

var UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36';
function jGet(url, headers) {
  try {
    var h = {'User-Agent': UA, 'Referer': SITE + '/'};
    if (headers) { for (var k in headers) h[k] = headers[k]; }
    return fetch(url, {headers: h});
  } catch (e) { return ''; }
}
function jUnesc(s) {
  if (!s) return '';
  return s.replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&#(\d+);/g, function (m, d) { return String.fromCharCode(parseInt(d, 10)); }).replace(/&#x([0-9a-fA-F]+);/g, function (m, h) { return String.fromCharCode(parseInt(h, 16)); });
}
function jAbs(u) {
  if (!u) return '';
  if (u.indexOf('//') === 0) return 'https:' + u;
  if (u.indexOf('/') === 0) return SITE + u;
  return u;
}
function jStrip(s) {
  if (!s) return '';
  return jUnesc(s.replace(/<[^>]+>/g, '')).replace(/\s+/g, ' ').trim();
}
function jText(s) {
  if (!s) return '';
  var t = s.replace(/<script[\s\S]*?<\/script>/gi, '').replace(/<style[\s\S]*?<\/style>/gi, '').replace(/<\/p\s*>/gi, '\n').replace(/<br\s*\/?>/gi, '\n');
  t = t.replace(/<[^>]+>/g, '');
  t = jUnesc(t);
  var lines = t.split('\n');
  var out = [];
  for (var i = 0; i < lines.length; i++) {
    var ln = lines[i].replace(/[ \t]+/g, ' ').trim();
    if (ln) out.push(ln);
  }
  return out.join('\n');
}
function jCls(defCls) {
  var c = defCls || '';
  try {
    if (typeof MY_URL !== 'undefined' && MY_URL) {
      var pp = String(MY_URL).split('##');
      if (pp.length > 1 && pp[1]) c = pp[1];
    }
  } catch (e) {}
  return c;
}
function jPage() {
  var p = 1;
  try { if (typeof MY_PAGE !== 'undefined' && MY_PAGE) p = parseInt(MY_PAGE) || 1; } catch (e) {}
  return p;
}
function jKw() {
  var k = '';
  try { if (typeof MY_KEYWORD !== 'undefined' && MY_KEYWORD) k = String(MY_KEYWORD); } catch (e) {}
  return k;
}
function jDurl() {
  var u = '';
  try { if (typeof MY_URL !== 'undefined' && MY_URL) u = String(MY_URL); } catch (e) {}
  return u;
}
function jNovelDetail(title, text) {
  var items = [];
  items.push({title: title || '详情', desc: '', url: 'hiker://empty'});
  if (text) {
    items.push({title: '小说', col_type: 'text_1', url: 'hiker://empty'});
    items.push({title: '阅读', url: 'novel://' + JSON.stringify({title: title, content: text})});
    items.push({title: '正文', col_type: 'text_center_1', extra: {lineVisible: false}, url: 'hiker://empty'});
    items.push({title: text.replace(/\n/g, '<br/>'), col_type: 'rich_text'});
  }
  return items;
}


var items = [];
try {
  var durl = jDurl();
  var html = jGet(durl);
  var tm = html.match(/<div class="article-title">\s*『([\s\S]*?)』\s*<\/div>/);
  var vtitle = '';
  if (tm) vtitle = jStrip(tm[1]);
  if (!vtitle) {
    var tt = html.match(/<title>([\s\S]*?)<\/title>/);
    if (tt) vtitle = jStrip(tt[1]).split(' - ')[0];
  }
  var xm = html.match(/<div class="artcontent">([\s\S]*?)<\/div>/);
  var text = xm ? jText(xm[1]) : '';
  items = jNovelDetail(vtitle, text);
} catch (e) { items = []; }
setResult(items);

