    var html = fetchTxt(postUrl, { headers: apiHeaders(), timeout: 15000 });
    var imgs = [];
    try {
      var am = html.match(/<article[^>]*class="[^"]*article-content[^"]*"[^>]*>([\s\S]*?)<\/article>/);
      if (am) {
        var imre = /<img[^>]+>/g;
        var im;
        while ((im = imre.exec(am[1])) !== null) {
          var dm = im[0].match(/data-original="([^"]+)"/);
          var sm2 = dm ? dm[1] : ((im[0].match(/src="([^"]+)"/) || [])[1] || "");
          if (sm2 && sm2.indexOf("http") === 0 && sm2.indexOf("thumbnail.png") < 0 && sm2.indexOf("logo.png") < 0 && imgs.indexOf(sm2) < 0) imgs.push(sm2);
        }
      }
    } catch (e) {}
    if (!imgs.length) return "toast://这个帖子没有图片";
    var cap = parseInt(maxN || "0", 10) || 0;
    if (cap > 0 && imgs.length > cap) imgs = imgs.slice(0, cap);
    return "pics://" + imgs.join("&&");
  } catch (e) { return "toast://打开失败"; }
}
