    });
  } catch (e) { return "hiker://empty"; }
}
// 视频流 302 解析（v1 的办法，不变）
function resolveMp4(src) {
  for (var att = 0; att < 5; att++) {
    try {
      var u = new java.net.URL(src + "?_t=" + String(Date.now()) + String(Math.random()).slice(2, 6));
      var c = u.openConnection();
      c.setConnectTimeout(8000);
      c.setReadTimeout(15000);
      c.setUseCaches(false);
      c.setInstanceFollowRedirects(false);
      c.setRequestMethod("GET");
      c.setRequestProperty("User-Agent", UA);
      c.setRequestProperty("Referer", VID_REF);
      var st = c.getResponseCode();
      var loc = "";
      try { loc = c.getHeaderField("Location") || ""; } catch (e) {}
      try { c.disconnect(); } catch (e2) {}
      if ((st === 301 || st === 302 || st === 303 || st === 307 || st === 308) && loc && loc.indexOf("http") === 0) return loc;
    } catch (e) {}
  }
  return "";
}
function playPlainUrl(tid) {
  try {
    var src = SRC_OF[tid] || VID_DOM;
    var mp4 = "";
    try { mp4 = resolveMp4(src); } catch (e) {}
    if (mp4) return mp4 + "#isVideo=true#";
    return src + "?_t=" + String(Date.now()) + ";{Referer@" + VID_REF + "}#isVideo=true#";
  } catch (e) { return "toast://播放解析失败"; }
}
