js:
var SITE = 'https://aabook.net';

var UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36';
function jGet(url, headers) {
  try {
    var h = {'User-Agent': UA, 'Referer': SITE + '/'};
    if (headers) { for (var k in headers) h[k] = headers[k]; }
    return fetch(url, {headers: h});
  } catch (e) { return ''; }
}
function jUnesc(s) {
  if (!s) return '';
  return s.replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&#(\d+);/g, function (m, d) { return String.fromCharCode(parseInt(d, 10)); }).replace(/&#x([0-9a-fA-F]+);/g, function (m, h) { return String.fromCharCode(parseInt(h, 16)); });
}
function jAbs(u) {
  if (!u) return '';
  if (u.indexOf('//') === 0) return 'https:' + u;
  if (u.indexOf('/') === 0) return SITE + u;
  return u;
}
function jStrip(s) {
  if (!s) return '';
  return jUnesc(s.replace(/<[^>]+>/g, '')).replace(/\s+/g, ' ').trim();
}
function jText(s) {
  if (!s) return '';
  var t = s.replace(/<script[\s\S]*?<\/script>/gi, '').replace(/<style[\s\S]*?<\/style>/gi, '').replace(/<\/p\s*>/gi, '\n').replace(/<br\s*\/?>/gi, '\n');
  t = t.replace(/<[^>]+>/g, '');
  t = jUnesc(t);
  var lines = t.split('\n');
  var out = [];
  for (var i = 0; i < lines.length; i++) {
    var ln = lines[i].replace(/[ \t]+/g, ' ').trim();
    if (ln) out.push(ln);
  }
  return out.join('\n');
}
function jCls(defCls) {
  var c = defCls || '';
  try {
    if (typeof MY_URL !== 'undefined' && MY_URL) {
      var pp = String(MY_URL).split('##');
      if (pp.length > 1 && pp[1]) c = pp[1];
    }
  } catch (e) {}
  return c;
}
function jPage() {
  var p = 1;
  try { if (typeof MY_PAGE !== 'undefined' && MY_PAGE) p = parseInt(MY_PAGE) || 1; } catch (e) {}
  return p;
}
function jKw() {
  var k = '';
  try { if (typeof MY_KEYWORD !== 'undefined' && MY_KEYWORD) k = String(MY_KEYWORD); } catch (e) {}
  return k;
}
function jDurl() {
  var u = '';
  try { if (typeof MY_URL !== 'undefined' && MY_URL) u = String(MY_URL); } catch (e) {}
  return u;
}
function jNovelDetail(title, text) {
  var items = [];
  items.push({title: title || '详情', desc: '', url: 'hiker://empty'});
  if (text) {
    items.push({title: '小说', col_type: 'text_1', url: 'hiker://empty'});
    items.push({title: '阅读', url: 'novel://' + JSON.stringify({title: title, content: text})});
    items.push({title: '正文', col_type: 'text_center_1', extra: {lineVisible: false}, url: 'hiker://empty'});
    items.push({title: text.replace(/\n/g, '<br/>'), col_type: 'rich_text'});
  }
  return items;
}


var MOBILE = SITE + '/m/';
function jAabookCards(html) {
  var out = [];
  if (!html) return out;
  var blocks = html.split('<li class="column-2');
  for (var i = 1; i < blocks.length; i++) {
    var b = blocks[i];
    var mid = b.match(/href="book-(\d+)\.html"/);
    var nm = b.match(/<a class="name" href="book-\d+\.html">([^<]+)<\/a>/);
    if (!mid || !nm) continue;
    var latest = b.match(/class="chapter">([^<]+)<\/a>/);
    var words = b.match(/字数：(\d+)/);
    var author = b.match(/作者：([^<\s]+)/);
    var remark = '';
    if (latest) remark = latest[1].trim();
    else if (words) remark = words[1] + '字';
    out.push({title: jStrip(nm[1]), img: SITE + '/img-' + mid[1] + '.jpg', desc: remark, url: MOBILE + 'book-' + mid[1] + '.html'});
  }
  return out;
}
function jChapterText(rid) {
  var readUrl = MOBILE + 'read-' + rid + '.html';
  for (var t = 0; t < 2; t++) {
    var page = jGet(readUrl);
    var tm = page.match(/_getcontent\.php\?id="\+chapid\+"&v=([A-Za-z0-9_\-]+)/);
    if (!tm) return {name: '', text: ''};
    var gc = jGet(SITE + '/_getcontent.php?id=' + rid + '&v=' + tm[1], {'Referer': readUrl, 'X-Requested-With': 'XMLHttpRequest'});
    if (gc.indexOf('<p>') < 0) continue;
    var paras = [];
    var pm = gc.match(/<p>([\s\S]*?)<\/p>/g);
    if (pm) {
      for (var i = 0; i < pm.length; i++) {
        var ln = jStrip(pm[i]);
        if (ln) paras.push(ln);
      }
    }
    var nm = page.match(/<title>([^<]*)<\/title>/);
    var name = nm ? nm[1].trim() : '';
    if (name.indexOf('在线全文阅读') >= 0) name = name.split('在线全文阅读')[0].trim();
    return {name: name, text: paras.join('\n')};
  }
  return {name: '', text: ''};
}

var items = [];
try {
  var durl = jDurl();
  var bm = durl.match(/(\d+)/);
  var bid = bm ? bm[1] : durl;
  var book = jGet(MOBILE + 'book-' + bid + '.html');
  var tm = book.match(/<h2>([^<]+)<\/h2>/);
  var vtitle = tm ? jStrip(tm[1]) : bid;
  var author = book.match(/作者：([^<\s]+)/);
  var words = book.match(/字数：(\d+)/);
  var status = book.match(/<span class="status"[^>]*>([^<]+)/);
  var remark = '';
  if (status) remark = status[1].trim();
  if (words) remark = (remark ? remark + ' ' : '') + words[1] + '字';
  items.push({title: vtitle, img: SITE + '/img-' + bid + '.jpg', desc: author ? author[1] : '', url: 'hiker://empty'});
  var chapters = [];
  var seen = {};
  for (var p = 1; p <= 40; p++) {
    var cpage = jGet(MOBILE + 'chapter.php?p=' + p + '&id=' + bid + '&ob=asc');
    var links = [];
    var lm = cpage.match(/href="(read-\d+\.html)"[^>]*>([^<]+)<\/a>/g);
    var fresh = 0;
    if (lm) {
      for (var i = 0; i < lm.length; i++) {
        var one = lm[i].match(/href="(read-\d+\.html)"[^>]*>([^<]+)<\/a>/);
        if (!one) continue;
        var rid = one[1].match(/(\d+)/)[1];
        if (seen[rid]) continue;
        seen[rid] = 1;
        fresh++;
        chapters.push({name: one[2].trim().replace(/#/g, ' ').replace(/\$/g, ' '), href: one[1], rid: rid});
      }
    }
    if (fresh === 0) break;
  }
  if (chapters.length) {
    var first = jChapterText(chapters[0].rid);
    if (first.text) {
      items.push({title: '小说', col_type: 'text_1', url: 'hiker://empty'});
      items.push({title: '阅读（第一章）', url: 'novel://' + JSON.stringify({title: first.name || chapters[0].name, content: first.text})});
