            if (!L || L.charAt(0) === '#') continue;
            if (/^https?:/.test(L)) return L + '#isM3u8##isVideo=true#';
            return absUrl(url, L) + '#isM3u8##isVideo=true#';
        }
    }
    return url + '#isM3u8##isVideo=true#';
}
function absUrl(base, p) {
    if (/^(https?:|data:|file:)/.test(p)) return p;
    var root = (String(base).match(/^(https?:\/\/[^\/]+)/) || [])[1] || '';
    if (p.charAt(0) === '/') return root + p;
    return String(base).substring(0, String(base).lastIndexOf('/') + 1) + p;
}
function localize(url) {
    var m3u = '';
    try { m3u = req(url); } catch (e0) { m3u = ''; }
    if (!m3u || m3u.indexOf('#EXTM3U') < 0) return url + '#isM3u8##isVideo=true#';
    var cur = String(url);
    if (m3u.indexOf('#EXT-X-STREAM-INF') >= 0) {
        var lines = m3u.split('\n');
        var variant = '';
        for (var i = 0; i < lines.length; i++) {
            var L = lines[i].replace(/\s+$/, '');
            if (!L || L.charAt(0) === '#') continue;
            variant = absUrl(cur, L);
            break;
        }
        if (variant) {
            var sub = req(variant);
            if (sub && sub.indexOf('#EXTM3U') >= 0) { cur = variant; m3u = sub; }
        }
    }
    /* 去贴片广告：按 DISCONTINUITY 分块，段数加权主目录之外的块整块丢弃 */
    m3u = stripAdBlocks(m3u);
    var root = (cur.match(/^(https?:\/\/[^\/]+)/) || [])[1] || '';
    var base = cur.substring(0, cur.lastIndexOf('/') + 1);
    var out = [];
    var ls = m3u.split('\n');
    for (var k = 0; k < ls.length; k++) {
