}
/* 贴片广告剥离：
   站点把广告作为独立目录的分片插在正片里，用 #EXT-X-DISCONTINUITY 隔开。
   判据：按"段数加权的主目录"识别正片目录，丢弃其他目录的块。
   为什么不用时长/段数：实测存在正片被切成 83 个短块（每块 1~22 段）的源，
   按时长判会把正片当广告删光；而按段数加权，该源全部块同目录 → 一块都不删。
   为什么不用单块目录计数：分片型正片块数极多，按块数会选错目录。 */
function stripAdBlocks(m3u) {
    var lines = String(m3u).split('\n');
    var blocks = [];
    var cur = [];
    for (var i = 0; i < lines.length; i++) {
        var L = lines[i].replace(/\s+$/, '');
        if (L.indexOf('#EXT-X-DISCONTINUITY') === 0 && cur.length) { blocks.push(cur); cur = []; }
        cur.push(L);
    }
    if (cur.length) blocks.push(cur);
    if (blocks.length < 2) return m3u;

    /* 文件头必须保留：#EXTM3U / VERSION / TARGETDURATION / MEDIA-SEQUENCE / PLAYLIST-TYPE 等，
       一旦丢失播放器会判定非法 m3u8（实测报"播放异常"）。
       文件头 = 第一个 #EXTINF 之前的所有行。 */
    var header = [];
    for (var h = 0; h < blocks[0].length; h++) {
        var HL = blocks[0][h];
        if (HL.indexOf('#EXTINF') === 0) break;
        header.push(HL);
    }

    /* 每个块取目录键（去掉文件名的完整目录），并统计段数 */
    var keys = [];
    var segCount = [];
    var weight = {};
    for (var b = 0; b < blocks.length; b++) {
        var segs = [];
        for (var s = 0; s < blocks[b].length; s++) {
            var S = blocks[b][s];
            if (S && S.charAt(0) !== '#') segs.push(S);
        }
        segCount.push(segs.length);
        var k = '';
        if (segs.length) {
            var first = String(segs[0]);
            var q = first.indexOf('?');
            if (q >= 0) first = first.substring(0, q);
            k = first.replace(/\/[^\/]*$/, '');
        }
        keys.push(k);
        if (k) weight[k] = (weight[k] || 0) + segs.length;
    }
    /* 只有一个目录 → 无插片，原样返回 */
    var dirs = [];
    for (var kk in weight) dirs.push(kk);
    if (dirs.length < 2) return m3u;

    var mainKey = '';
    var best = 0;
    for (var d = 0; d < dirs.length; d++) {
        if (weight[dirs[d]] > best) { best = weight[dirs[d]]; mainKey = dirs[d]; }
    }
    if (!mainKey) return m3u;

    var keep = [];
    var dropped = 0;
    for (var j = 0; j < blocks.length; j++) {
        if (segCount[j] === 0) { continue; }        /* 空块直接丢 */
        if (keys[j] !== mainKey) { dropped++; continue; }
        keep.push(blocks[j]);
    }
    if (!keep.length || dropped === 0) return m3u;
    var res = [];
    /* 先写回文件头 */
    for (var hh = 0; hh < header.length; hh++) {
        if (header[hh] !== '') res.push(header[hh]);
    }
    if (!res.length || res[0].indexOf('#EXTM3U') !== 0) res.unshift('#EXTM3U');
    for (var x = 0; x < keep.length; x++) {
        for (var y = 0; y < keep[x].length; y++) {
            var T = keep[x][y];
            if (T.indexOf('#EXT-X-DISCONTINUITY') === 0) continue;
            if (T.indexOf('#EXTINF') !== 0 && T.charAt(0) === '#' && header.indexOf(T) >= 0) continue;
            if (T === '') continue;
            res.push(T);
        }
    }
    return res.join('\n');
}

