    if(!body){
      m = html.match(/class="[^"]*(?:content|novel|article|text)[^"]*"[^>]*>([\s\S]{200,})/i);
      if(m) body = m[1].substring(0, 100000);
    }
    body = body
      .replace(/<script[\s\S]*?<\/script>/gi, '')
      .replace(/<style[\s\S]*?<\/style>/gi, '')
      .replace(/<br\s*\/?>/gi, '\n')
      .replace(/<\/p>/gi, '\n')
      .replace(/<[^>]+>/g, '')
      .replace(/&nbsp;/g, ' ')
      .replace(/&amp;/g, '&')
      .replace(/\n{3,}/g, '\n\n');
    if(!body || body.replace(/\s/g, '').length < 10){
      d.push({ title: '暂无正文', url: 'hiker://empty', col_type: 'text_center_1' });
    }else{
      d.push({ title: body, url: 'hiker://empty', col_type: 'long_text' });
