        }
        let tit = it.title || "";
        it = it.text || "";
        if (it == "" || it.length > 8) {
            return false;
        }
        //排除
        let reg = /\.|高清直播|写真推荐|影院|影视|蓝光电影|高清电影|第一季|第二季|第三季|第四季|第五季/;
