        }
        it = clearText(it);
        let reg = /^[0-9]*$/;
        if (!reg.test(it)) {
            return -1;
        }
        it = parseInt(it);
        if (isNaN(it)) {
            return -1;
        }
        if (it > 1900 && it < 2100) {
            return -1;
        }
        return it;
    }

