    var sep = path.indexOf('?') === -1 ? '?' : '&';
    var url = TMDB_API + path + sep + "language=zh-CN";
    if (params) {
        for (var k in params) {
            url += "&" + k + "=" + encodeURIComponent(params[k]);
        }
    }
    try {
        var resp = fetch(url, {
            headers: {
                "User-Agent": "Mozilla/5.0",
                "Authorization": "Bearer " + TMDB_KEY
            },
            timeout: 10000
        });
        if (!resp || resp.trim() === '') {
            return { error: "TMDB接口无响应，请检查网络或代理地址" };
