        var trimmed = resp.replace(/^\s+/, '');
        if (trimmed.charAt(0) === '<') {
            log("TMDB返回HTML: path=" + path + " | " + trimmed.substring(0, 150));
            return { error: "TMDB代理返回HTML: " + path };
