        config.platform = String(saved.danmu_platform || '').trim();
        config.timeout = (parseInt(saved.danmu_timeout, 10) || 3) * 1000;
        config.sources = (saved.danmu_sources || []).filter(function(item) { return item && item.url && item.enabled === true; });
