function qdShare(type, data) {
    var sharelist = [];
    if (Array.isArray(data)) {
        for (var i = 0; i < data.length; i++) {
            var item = data[i];
            if (item._xj_type) {
                sharelist.push(item);
            } else if (item.type === 'parse' || item._type === 'parse') {
                sharelist.push({_xj_type: 'parse', name: item.name, type: item.type === 'parse' ? (item.parseType || '') : item.type, url: item.url, Names: item.Names || '', jsCode: item.jsCode || '', enabled: item.enabled !== false});
            } else if (item.type === 'bocai' || item._type === 'bocai') {
                sharelist.push({_xj_type: 'bocai', key: item.key, name: item.name, api: item.api, detail: item.detail || '', enabled: item.enabled !== false});
            } else if (item.type === 'rule' || item._type === 'rule') {
                var ruleCode = '';
                try { ruleCode = readFile(item.url) || item.code || ''; } catch(e) { ruleCode = item.code || ''; }
                sharelist.push({_xj_type: 'rule', name: item.name, '类型': item['类型'] || '', code: ruleCode, enabled: item.enabled !== false});
            }
        }
    } else if (type === 'parse') {
        sharelist.push({_xj_type: 'parse', name: data.name, type: data.type, url: data.url, Names: data.Names || '', jsCode: data.jsCode || '', enabled: data.enabled !== false});
    } else if (type === 'bocai') {
        sharelist.push({_xj_type: 'bocai', key: data.key, name: data.name, api: data.api, detail: data.detail || '', enabled: data.enabled !== false});
    } else if (type === 'rule') {
        var ruleCode = '';
        try { ruleCode = readFile(data.url) || ''; } catch(e) {}
        sharelist.push({_xj_type: 'rule', name: data.name, '类型': data['类型'] || '', code: ruleCode, enabled: data.enabled !== false});
    }
    if (sharelist.length === 0) return "toast://无有效数据可分享";
    var gzip = $.require("gzip.js");
    var sharetxt = gzip.zip(JSON.stringify(sharelist));
    var sm = sharelist.length > 1 ? '星集接口' : (type === 'parse' ? '星集解析' : (type === 'bocai' ? '星集采集' : '星集规则'));
    var sm2 = sharelist.length > 1 ? ('共' + sharelist.length + '条') : sharelist[0].name;
    var importJs = '@import=js:writeFile("hiker://files/_cache/xj_cloudimport.txt",input);"hiker://page/parse#noRecordHistory##noHistory#?rule=星集Media";';
    putMyVar('xj_share_txt', sharetxt);
    putMyVar('xj_share_sm', sm);
    putMyVar('xj_share_sm2', sm2);
    putMyVar('xj_share_importJs', importJs);
    var pastes = typeof getPastes === 'function' ? getPastes() : [];
    pastes = pastes.filter(function(v) { return !/云剪贴板[59]|云剪贴板10/.test(v); });
    pastes.push('云口令文件');
    if (pastes.length > 1) {
        return $(pastes, 2, '选择分享方式').select(function() {
            var sharetxt = getMyVar('xj_share_txt');
            var sm = getMyVar('xj_share_sm');
            var sm2 = getMyVar('xj_share_sm2');
            var importJs = getMyVar('xj_share_importJs');
            if (input === '云口令文件') {
                var code = sm + '￥' + aesEncode('Qingdou', sharetxt) + '￥云口令文件';
                var sharefile = 'hiker://files/_cache/【星集源】_' + sm2 + '_' + Date.now() + '.hiker';
                saveFile(sharefile, '云口令：' + code + importJs);
                if (fileExist(sharefile)) return 'share://' + sharefile;
                return "toast://分享生成失败";
            } else {
                showLoading('分享生成中...');
                var pasteurl = sharePaste(sharetxt, input);
                hideLoading();
                if (/^http|^云/.test(pasteurl) && pasteurl.includes('/')) {
                    var code = sm + '￥' + aesEncode('Qingdou', pasteurl) + '￥' + sm2 + '(' + input.replace('剪贴板', '') + ')';
                    copy('云口令：' + code + importJs);
                    return "toast://分享口令已复制到剪贴板";
                } else {
                    return "toast://分享失败，剪粘板或网络异常>" + pasteurl;
                }
            }
        });
    }
    try {
        if (pastes.length > 0 && pastes[0] !== '云口令文件') {
            showLoading('分享生成中...');
