    if (fileExist(sharefile)) return 'share://' + sharefile;
    return "toast://分享生成失败";
}

function qdExtractImport(str) {
    showLoading('获取数据中...');
    var strs = str.replace(/\\n|云口令：/g, '').split('@import=');
    strs = strs.filter(function(v) { return v && /星集(解析|采集|规则|接口)￥/.test(v); });
    var datas = [];
    for (var i = 0; i < strs.length; i++) {
        try {
            var code = aesDecode('Qingdou', strs[i].split('￥')[1]);
            var text;
            if (/^http|^云/.test(code)) {
                text = parsePaste(code);
            } else {
                text = code;
            }
            if (text && !/^error/.test(text)) {
                var gzip = $.require("gzip.js");
                var sharetxt = gzip.unzip(text);
                var imports = JSON.parse(sharetxt);
                for (var j = 0; j < imports.length; j++) {
                    if (!datas.some(function(v) { return v._xj_type === imports[j]._xj_type && v.name === imports[j].name; })) {
                        datas.unshift(imports[j]);
                    }
                }
            }
        } catch(e) {
            log('星集：获取口令数据出错>' + e.message);
        }
    }
    hideLoading();
    return datas;
}

