        return String(java.util.Base64.getEncoder().encodeToString(compressed));
    } catch (e) { return null; }
}
function gzipDecompress(b64) {
    try {
        var compressed = java.util.Base64.getDecoder().decode(b64);
        var bais = new java.io.ByteArrayInputStream(compressed);
        var gis = new java.util.zip.GZIPInputStream(bais);
        var baos = new java.io.ByteArrayOutputStream();
        var buffer = java.lang.reflect.Array.newInstance(java.lang.Byte.TYPE, 1024);
        var len;
        while ((len = gis.read(buffer)) != -1) { baos.write(buffer, 0, len); }
        gis.close();
        bais.close();
        baos.close();
        return String(new java.lang.String(baos.toByteArray(), "UTF-8"));
    } catch (e) { return null; }
}
function getLayerCache(layer, cacheKey, ttl) {
