        renderEpList(obj, activeLine, isCacheHit);
        updateItem(anchorId, { col_type: 'line', extra: { id: anchorId } });
        return { categories: categories, activeCategory: activeCat, activeLine: activeLine, isCacheHit: isCacheHit };
