    if (fileHtml.audit && fileHtml.audit.title) return "toast://" + fileHtml.audit.title;

    if (savedMime && savedMime.includes("video")) {
        var dlLink = "";
        if (fileHtml.links && fileHtml.links["application/octet-stream"]) {
            dlLink = fileHtml.links["application/octet-stream"].url;
        }
        if (!dlLink) return "hiker://empty";

        var names = ["原始画质"];
        var urls = [dlLink + "#isVideo=true##fastPlayMode##threads=" + getItem("xunleiThread", "24") + "#"];
        var headers = [getHeader()];

        if (fileHtml.medias) {
            var resolutionMap = {"low": "480P流畅", "normal": "720P标清", "high": "1080P高清", "super": "1080P超清", "2k": "2K超清", "4k": "4K极致", "8k": "8K"};
            for (var i = 0; i < fileHtml.medias.length; i++) {
                var m = fileHtml.medias[i];
                if (m.link) {
                    var mName = resolutionMap[m.media_name] || m.media_name;
                    names.push(mName);
                    urls.push(m.link.url + "#isVideo=true##fastPlayMode##threads=" + getItem("xunleiThread", "24") + "#");
