        return JSON.stringify({names: names, urls: urls, headers: headers, danmu: dmPath});
    }

    if (savedMime && savedMime.includes("audio")) {
        if (fileHtml.links && fileHtml.links["application/octet-stream"]) {
            return JSON.stringify({urls: [fileHtml.links["application/octet-stream"].url + "#isMusic=true#"], headers: [getHeader()]});
        }
    }

    if (dlLink) return "download://" + dlLink;
    return "hiker://empty";
}

