        open: '∨',
        close: '∧'
    },
    COLORS: {
        fold: "#FF0000",
        unfold: "#1aad19",
        category: 分类颜色 || "#12b668"
    }
};

// 获取分类数据
function getCategories() {
    const baseCates = pdfa(html, 大类定位);
    return typeof 拼接分类 !== 'undefined' && 拼接分类 
        ? baseCates.concat(pdfa(html, 拼接分类))
        : baseCates;
}

// 创建分类按钮
function createCategoryButton(item, key, index, resetOthers, currentSelected) {
    let title = pdfh(item, 分类标题);

    // 安全检查排除变量
    if (typeof 排除 !== 'undefined' && 排除) {
        title = title.replace(new RegExp(排除, "g"), "");
    }

    const isSelected = key.toString() === currentSelected[index];
    const displayTitle = isSelected ? `““””${title.fontcolor(CONFIG.COLORS.category)}` : title;

    return {
        title: displayTitle,
        url: $(pd(item, 分类链接) + '#noLoading#').lazyRule((params) => {
            const newCate = params.currentSelected.map((c, i) => 
                params.resetOthers 
                    ? (i === params.index ? params.key.toString() : "0")
                    : (i === params.index ? params.key.toString() : c)
            );

            putMyVar(MY_RULE.title, JSON.stringify(newCate));
            putMyVar(MY_RULE.url, input);
            refreshPage(true);
            return "hiker://empty";
        }, { 
            currentSelected: currentSelected, 
            index: index, 
            key: key, 
            resetOthers: resetOthers 
        }),
        col_type: 'scroll_button',
    };
}

// 创建折叠按钮
function createFoldButton(currentFoldState) {
    const isFolded = currentFoldState === '1';
    const icon = isFolded ? CONFIG.FOLD_ICONS.open : CONFIG.FOLD_ICONS.close;
    const color = isFolded ? CONFIG.COLORS.fold : CONFIG.COLORS.unfold;

    return {
        title: `““””<b>${icon.fontcolor(color)}</b>`,
        url: $().lazyRule((f) => {
            putMyVar(MY_RULE.group, f === '1' ? '0' : '1');
            refreshPage(false);
            return "hiker://empty";
        }, currentFoldState),
        col_type: 'scroll_button',
    };
}

// 主函数
function buildCategoryUI() {
    const result = [];
    const categories = getCategories();
    const foldState = getMyVar(MY_RULE.group, CONFIG.FOLD_DEFAULT);
    const currentCate = JSON.parse(getMyVar(MY_RULE.title, JSON.stringify(CONFIG.INIT_CATE)));

    if (parseInt(MY_PAGE) === 1) {
        result.push(createFoldButton(foldState));

        categories.forEach((category, index) => {
            const subCategories = pdfa(category, 小类定位);
            if (index === 0 || foldState === '1') {
                subCategories.forEach((item, key) => {
                    result.push(createCategoryButton(item, key,index,index === 0,currentCate));
                });
                result.push({ col_type: "blank_block" });
            }
        });
    }
    return result;
}
