    var count = 0x0;
    var base = 0x0;
    for (var i = 0x0; i < pt.length; i += 0x4) {
        count += parseInt(pt[i] + pt[i + 0x1] + pt[i + 0x2] + pt[i + 0x3], 0x10);
        count %= 0x400a;
    }
    base = count % 0xa;
    var param = 0x0;
    for (var a = 0x0; a < pt.length; a++) {
        param += pt.charCodeAt(a) * (a + base);
        param %= count;
    }
    return param + '';
}


